export default {"html":"<p data-line=\"0\" class=\"code-line\">When you use Ionic, you run an initialization method for your framework. In Angular that is <code>provideIonicAngular</code>; in React, <code>setupIonicReact</code>; in Vue, inside <code>use</code> on <code>createApp</code>.</p>\n<p data-line=\"2\" class=\"code-line\">Passing arguments there overrides Ionic's initial settings app-wide. Options include enabling or disabling animations, platform style, hardware back button behavior, status bar tap behavior, icon customization, custom animations, security settings, and more.</p>\n<p data-line=\"4\" class=\"code-line\">This article revisits Ionic's global configuration and explains what each option means and how to use it.</p>\n<h2 id=\"how-to-configure\" data-line=\"6\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#how-to-configure\" aria-hidden=\"true\"></a> How to configure</h2>\n<h3 id=\"angular\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#angular\" aria-hidden=\"true\"></a> Angular</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"10\"><span class=\"line\"><span style=\"color:#B392F0\">provideIonicAngular</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  rippleEffect: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  mode: </span><span style=\"color:#9ECBFF\">'md'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"react\" data-line=\"17\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#react\" aria-hidden=\"true\"></a> React</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"19\"><span class=\"line\"><span style=\"color:#B392F0\">setupIonicReact</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  rippleEffect: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  mode: </span><span style=\"color:#9ECBFF\">'md'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"vue\" data-line=\"26\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#vue\" aria-hidden=\"true\"></a> Vue</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"28\"><span class=\"line\"><span style=\"color:#B392F0\">createApp</span><span style=\"color:#E1E4E8\">(App).</span><span style=\"color:#B392F0\">use</span><span style=\"color:#E1E4E8\">(IonicVue, {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  rippleEffect: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  mode: </span><span style=\"color:#9ECBFF\">'md'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"ionicconfig-in-depth-%E2%80%94-settings-to-customize-your-app\" data-line=\"35\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ionicconfig-in-depth-%E2%80%94-settings-to-customize-your-app\" aria-hidden=\"true\"></a> IonicConfig in depth — settings to customize your app</h2>\n<h3 id=\"animation-and-visual-effects\" data-line=\"37\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#animation-and-visual-effects\" aria-hidden=\"true\"></a> Animation and visual effects</h3>\n<ul data-line=\"39\" class=\"code-line\">\n<li data-line=\"39\" class=\"code-line\">\n<p data-line=\"39\" class=\"code-line\"><strong><code>animated?: boolean</code></strong>: Enables or disables animations and transitions app-wide. Default is <code>true</code>. On low-end devices where animations stutter, set <code>false</code> for smoother motion. Balance performance and user experience.</p>\n</li>\n<li data-line=\"41\" class=\"code-line\">\n<p data-line=\"41\" class=\"code-line\"><strong><code>rippleEffect?: boolean</code></strong>: Enables or disables Material Design ripple effects. Default is <code>true</code>. Disable on low-end devices or when ripples are unnecessary.</p>\n</li>\n</ul>\n<h3 id=\"platform-and-hardware-integration\" data-line=\"44\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#platform-and-hardware-integration\" aria-hidden=\"true\"></a> Platform and hardware integration</h3>\n<ul data-line=\"46\" class=\"code-line\">\n<li data-line=\"46\" class=\"code-line\">\n<p data-line=\"46\" class=\"code-line\"><strong><code>mode?: Mode</code></strong>: Sets the platform style app-wide: <code>ios</code>, <code>md</code> (Material Design), <code>auto</code>, and others. <code>auto</code> picks based on the device OS. Use this when you want a platform-specific look and feel.</p>\n</li>\n<li data-line=\"48\" class=\"code-line\">\n<p data-line=\"48\" class=\"code-line\"><strong><code>hardwareBackButton?: boolean</code></strong>: Enables the Android hardware back button. Default is <code>true</code> on mobile. Set <code>false</code> to disable it.</p>\n</li>\n<li data-line=\"50\" class=\"code-line\">\n<p data-line=\"50\" class=\"code-line\"><strong><code>statusTap?: boolean</code></strong>: Scrolls to the top when the status bar is tapped. Default is <code>true</code> on mobile.</p>\n</li>\n</ul>\n<h3 id=\"back-button-and-menu-button-customization\" data-line=\"53\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#back-button-and-menu-button-customization\" aria-hidden=\"true\"></a> Back button and menu button customization</h3>\n<ul data-line=\"55\" class=\"code-line\">\n<li data-line=\"55\" class=\"code-line\">\n<p data-line=\"55\" class=\"code-line\"><strong><code>backButtonIcon?: string</code></strong>: Overrides the default icon for all <code>&lt;ion-back-button&gt;</code> components. Handy for custom icons.</p>\n</li>\n<li data-line=\"57\" class=\"code-line\">\n<p data-line=\"57\" class=\"code-line\"><strong><code>backButtonText?: string</code></strong>: Overrides the default text for all <code>&lt;ion-back-button&gt;</code> components.</p>\n</li>\n<li data-line=\"59\" class=\"code-line\">\n<p data-line=\"59\" class=\"code-line\"><strong><code>backButtonDefaultHref?: string</code></strong>: Overrides the default <code>href</code> for all <code>&lt;ion-back-button&gt;</code> components.</p>\n</li>\n<li data-line=\"61\" class=\"code-line\">\n<p data-line=\"61\" class=\"code-line\"><strong><code>menuIcon?: string</code></strong>: Overrides the default icon for all <code>&lt;ion-menu-button&gt;</code> components.</p>\n</li>\n<li data-line=\"63\" class=\"code-line\">\n<p data-line=\"63\" class=\"code-line\"><strong><code>menuType?: string</code></strong>: Overrides the default menu type for all <code>&lt;ion-menu&gt;</code> components. By default it follows the app mode.</p>\n</li>\n</ul>\n<h3 id=\"spinner%2C-toggle%2C-and-other-component-defaults\" data-line=\"66\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#spinner%2C-toggle%2C-and-other-component-defaults\" aria-hidden=\"true\"></a> Spinner, toggle, and other component defaults</h3>\n<ul data-line=\"68\" class=\"code-line\">\n<li data-line=\"68\" class=\"code-line\">\n<p data-line=\"68\" class=\"code-line\"><strong><code>spinner?: SpinnerTypes</code></strong>: Overrides the default spinner for all <code>&lt;ion-spinner&gt;</code> components. By default it follows the mode (<code>ios</code> or <code>md</code>).</p>\n</li>\n<li data-line=\"70\" class=\"code-line\">\n<p data-line=\"70\" class=\"code-line\"><strong><code>toggleOnOffLabels?: boolean</code></strong>: Enables or disables default on/off labels for all <code>&lt;ion-toggle&gt;</code> components.</p>\n</li>\n<li data-line=\"72\" class=\"code-line\">\n<p data-line=\"72\" class=\"code-line\"><strong><code>loadingSpinner?: SpinnerTypes | null</code></strong>: Overrides the default spinner for all <code>ion-loading</code> overlays created by <code>ion-loading-controller</code>.</p>\n</li>\n<li data-line=\"74\" class=\"code-line\">\n<p data-line=\"74\" class=\"code-line\"><strong><code>refreshingIcon?: string</code></strong>: Overrides the default icon for all <code>&lt;ion-refresh-content&gt;</code> components.</p>\n</li>\n<li data-line=\"76\" class=\"code-line\">\n<p data-line=\"76\" class=\"code-line\"><strong><code>refreshingSpinner?: SpinnerTypes | null</code></strong>: Overrides the default spinner type for all <code>&lt;ion-refresh-content&gt;</code> components.</p>\n</li>\n<li data-line=\"78\" class=\"code-line\">\n<p data-line=\"78\" class=\"code-line\"><strong><code>infiniteLoadingSpinner?: SpinnerTypes | null</code></strong>: Overrides the default spinner type for all <code>&lt;ion-infinite-scroll-content&gt;</code> components.</p>\n</li>\n</ul>\n<h3 id=\"gestures-and-navigation\" data-line=\"81\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#gestures-and-navigation\" aria-hidden=\"true\"></a> Gestures and navigation</h3>\n<ul data-line=\"83\" class=\"code-line\">\n<li data-line=\"83\" class=\"code-line\">\n<p data-line=\"83\" class=\"code-line\"><strong><code>swipeBackEnabled?: boolean</code></strong>: Enables or disables swipe-to-go-back app-wide. Default is <code>true</code>.</p>\n</li>\n<li data-line=\"85\" class=\"code-line\">\n<p data-line=\"85\" class=\"code-line\"><strong><code>tabButtonLayout?: TabButtonLayout</code></strong>: Overrides the default layout for all <code>ion-bar-button</code> elements.</p>\n</li>\n</ul>\n<h3 id=\"animation-customization\" data-line=\"88\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#animation-customization\" aria-hidden=\"true\"></a> Animation customization</h3>\n<p data-line=\"90\" class=\"code-line\"><code>navAnimation</code>, <code>actionSheetEnter</code>, <code>alertEnter</code>, <code>loadingEnter</code>, <code>modalEnter</code>, <code>popoverEnter</code>, <code>toastEnter</code>, <code>pickerEnter</code>, <code>actionSheetLeave</code>, <code>alertLeave</code>, <code>loadingLeave</code>, <code>modalLeave</code>, <code>popoverLeave</code>, <code>toastLeave</code>, and <code>pickerLeave</code> customize enter/leave animations for the matching Ionic overlays. Use <code>AnimationBuilder</code> for custom animations. Advanced customization.</p>\n<h3 id=\"security-and-other-settings\" data-line=\"93\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#security-and-other-settings\" aria-hidden=\"true\"></a> Security and other settings</h3>\n<ul data-line=\"95\" class=\"code-line\">\n<li data-line=\"95\" class=\"code-line\">\n<p data-line=\"95\" class=\"code-line\"><strong><code>sanitizerEnabled?: boolean</code></strong>: Enables a basic DOM sanitizer for properties on components that accept custom HTML. Set <code>true</code> for stronger security.</p>\n</li>\n<li data-line=\"97\" class=\"code-line\">\n<p data-line=\"97\" class=\"code-line\"><strong><code>innerHTMLTemplatesEnabled?: boolean</code></strong>: Enables use of <code>innerHTML</code>. Consider security risks and keep <code>false</code> unless you need it.</p>\n</li>\n<li data-line=\"99\" class=\"code-line\">\n<p data-line=\"99\" class=\"code-line\"><strong><code>platform?: PlatformConfig</code></strong>: Overrides default platform detection.</p>\n</li>\n<li data-line=\"101\" class=\"code-line\">\n<p data-line=\"101\" class=\"code-line\"><strong><code>focusManagerPriority?: FocusManagerPriority[]</code></strong>: Moves focus to the right element after page transitions. Improves accessibility. (Experimental.)</p>\n</li>\n<li data-line=\"103\" class=\"code-line\">\n<p data-line=\"103\" class=\"code-line\"><strong><code>experimentalCloseWatcher?: boolean</code></strong>: Uses the Close Watcher API so Escape and the hardware back button close menus and overlays and handle navigation. (Experimental; requires <code>hardwareBackButton: true</code>.)</p>\n</li>\n<li data-line=\"106\" class=\"code-line\">\n<p data-line=\"106\" class=\"code-line\"><strong><code>keyboardHeight</code>, <code>inputShims</code>, <code>scrollPadding</code>, <code>inputBlurring</code>, <code>scrollAssist</code>, <code>hideCaretOnScroll</code>, <code>persistConfig</code>, <code>_forceStatusbarPadding</code>, <code>_testing</code>, <code>_zoneGate</code>, <code>_ael</code>, <code>_rel</code>, <code>_ce</code></strong>: Internal settings you normally should not touch directly.</p>\n</li>\n</ul>\n<h2 id=\"summary\" data-line=\"109\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"111\" class=\"code-line\">I hope this helps you understand <code>IonicConfig</code> and build Ionic apps with finer control. Setting each option appropriately improves user experience and performance. For details, see the official documentation.</p>\n<p data-line=\"113\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"how-to-configure","text":"How to configure","level":2},{"id":"angular","text":"Angular","level":3},{"id":"react","text":"React","level":3},{"id":"vue","text":"Vue","level":3},{"id":"ionicconfig-in-depth-%E2%80%94-settings-to-customize-your-app","text":"IonicConfig in depth — settings to customize your app","level":2},{"id":"animation-and-visual-effects","text":"Animation and visual effects","level":3},{"id":"platform-and-hardware-integration","text":"Platform and hardware integration","level":3},{"id":"back-button-and-menu-button-customization","text":"Back button and menu button customization","level":3},{"id":"spinner%2C-toggle%2C-and-other-component-defaults","text":"Spinner, toggle, and other component defaults","level":3},{"id":"gestures-and-navigation","text":"Gestures and navigation","level":3},{"id":"animation-customization","text":"Animation customization","level":3},{"id":"security-and-other-settings","text":"Security and other settings","level":3},{"id":"summary","text":"Summary","level":2}]} as const;
